class Solution:
    def rangeSum(self, nums, n, left, right):
        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x
        total_sum = prefix[n]

        def count_leq(target):
            if target < 0:
                return 0
            l = 0
            count = 0
            for r in range(n):
                while prefix[r + 1] - prefix[l] > target:
                    l += 1
                count += r - l + 1
            return count

        def sum_and_count_leq(target):
            if target < 0:
                return 0, 0
            l = 0
            prefix_starts = 0
            total_count = 0
            total_sum_leq = 0
            for r in range(n):
                current = prefix[r + 1]
                while current - prefix[l] > target:
                    prefix_starts -= prefix[l]
                    l += 1
                count = r - l + 1
                total_sum_leq += count * current - prefix_starts
                total_count += count
                prefix_starts += current
            return total_count, total_sum_leq

        def first_k_sum(k):
            if k <= 0:
                return 0
            lo, hi = 1, total_sum
            while lo < hi:
                mid = (lo + hi) // 2
                if count_leq(mid) >= k:
                    hi = mid
                else:
                    lo = mid + 1
            count, total = sum_and_count_leq(lo)
            return total - (count - k) * lo

        return (first_k_sum(right) - first_k_sum(left - 1)) % MOD

