import java.io.*;
import java.util.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    public int rangeSum(int[] nums, int n, int left, int right) {
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }
        long totalSum = prefix[n];

        long rightSum = firstKSum(prefix, n, totalSum, right);
        long leftSum = firstKSum(prefix, n, totalSum, left - 1);
        long answer = (rightSum - leftSum) % MOD;
        if (answer < 0) answer += MOD;
        return (int) answer;
    }

    private long countLE(long[] prefix, int n, long target) {
        if (target < 0) return 0;
        int l = 0;
        long count = 0;
        for (int r = 0; r < n; r++) {
            while (prefix[r + 1] - prefix[l] > target) {
                l++;
            }
            count += r - l + 1L;
        }
        return count;
    }

    private long firstKSum(long[] prefix, int n, long totalSum, int k) {
        if (k <= 0) return 0;

        long lo = 1;
        long hi = totalSum;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (countLE(prefix, n, mid) >= k) hi = mid;
            else lo = mid + 1;
        }

        long target = lo;
        int l = 0;
        long prefixStarts = 0;
        long totalCount = 0;
        long totalValue = 0;

        for (int r = 0; r < n; r++) {
            long current = prefix[r + 1];
            while (current - prefix[l] > target) {
                prefixStarts -= prefix[l];
                l++;
            }
            long count = r - l + 1L;
            totalValue += count * current - prefixStarts;
            totalCount += count;
            prefixStarts += current;
        }

        return totalValue - (totalCount - k) * target;
    }
}

