        int n = static_cast<int>(prefix.size()) - 1;
        long long totalSum = prefix[n];

        long long lo = 1, hi = totalSum;
        while (lo < hi) {
            long long mid = lo + (hi - lo) / 2;
            if (countLE(prefix, mid) >= k) hi = mid;
            else lo = mid + 1;
