        vector<long long> prefix(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        long long answer = (firstKSum(prefix, right) -
                            firstKSum(prefix, left - 1)) % MOD;
        if (answer < 0) answer += MOD;
