static vector<string> splitTopLevel(const string& s) {
    vector<string> parts;
    int depth = 0;
    size_t start = 0;

    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '[') ++depth;
        else if (c == ']') --depth;
        else if (c == ',' && depth == 0) {
            parts.push_back(s.substr(start, i - start));
            start = i + 1;
