static vector<int> parseIntArray(const string& s) {
    string body = s.substr(1, s.size() - 2);
    if (body.find_first_not_of(" \t\r\n") == string::npos) return {};

    vector<string> parts = splitTopLevel(body);
    vector<int> result;
    result.reserve(parts.size());

    for (string part : parts) {
        size_t a = part.find_first_not_of(" \t\r\n");
        size_t b = part.find_last_not_of(" \t\r\n");
        result.push_back(stoi(part.substr(a, b - a + 1)));
    }
    return result;
}

